22	    public TokenQueue(String data) {
23	        reader = new CharacterReader(data);
24	    }
25	
26	    /**
27	     Is the queue empty?
28	     @return true if no data left in queue.
29	     */
30	    public boolean isEmpty() {
31	        return reader.isEmpty();
32	    }
33	
34	    /**
35	     Consume one character off queue.
36	     @return first character on queue.
37	     */
38	    public char consume() {
39	        return reader.consume();
40	    }
