49	    char current() {
50	        return reader.current();
51	    }
52	
53	    /**
54	     Tests if the next characters on the queue match the sequence, case-insensitively.
55	     @param seq String to check queue for.
56	     @return true if the next characters match.
57	     */
58	    public boolean matches(String seq) {
59	        return reader.matchesIgnoreCase(seq);
60	    }
