76	    /**
77	     If the queue case-insensitively matches the supplied string, consume it off the queue.
78	     @param seq String to search for, and if found, remove from queue.
79	     @return true if found and removed, false if not found.
80	     */
81	    public boolean matchChomp(String seq) {
