private static int indexOfTopLevelOf(String arg) {
    int found = -1;
    int depth = 0; // (), [], {}
    char quote = 0; // active quote char: ', ", or 0
    boolean escaped = false; // previous char was an unescaped backslash

    for (int i = 0; i < arg.length(); i++) {
        char c = arg.charAt(i);

        if (escaped) {
            escaped = false;
            continue;
        }
        if (c == '\\') {
            escaped = true;
            continue;
        }
        if (quote != 0) {
            if (c == quote) quote = 0;
            continue;
        }
        if (c == '\'' || c == '"') {
            quote = c;
            continue;
        }
        if (c == '(' || c == '[' || c == '{') {
            depth++;
            continue;
        }
        if (c == ')' || c == ']' || c == '}') {
            depth--;
            continue;
        }
        if (depth == 0 && (c == 'o' || c == 'O')) { // cheap pre-check, with full check below
            if (matchesTopLevelOfAt(arg, i)) {
                if (found != -1)
                    throw new Selector.SelectorParseException(
                        "Could not parse nth-index '%s': multiple 'of' clauses are not allowed", arg);
                found = i;
                i++; // skip the 'f'
            }
        }
    }
    return found;
}

/** True if {@code arg} at {@code i} is an {@code of} keyword bounded by whitespace on both sides. */
private static boolean matchesTopLevelOfAt(String arg, int i) {
    if (i + 1 >= arg.length() || (arg.charAt(i + 1) != 'f' && arg.charAt(i + 1) != 'F'))
        return false;
    if (i == 0 || !StringUtil.isWhitespace(arg.charAt(i - 1)))
        return false;
    int after = i + 2;
    return after < arg.length() && StringUtil.isWhitespace(arg.charAt(after));
}

